css:
:scope{display:block;width:100%}
.pw{--ink:#010A12;--bone:#EDE6D8;--stone:#E0D9CB;--sand:#BBAFA3;--clay:#8C5B46;--gilt:#C6A15B;--head:'Cormorant Garamond',serif;--body:'EB Garamond',serif;--label:'Montserrat',sans-serif;position:relative;font-family:var(--body);font-size:21px;line-height:1.5;font-weight:400;letter-spacing:0;-webkit-font-smoothing:antialiased;text-align:left;background:var(--stone);color:var(--ink)}
.pw *{box-sizing:border-box}
:where(.pw p,.pw h1,.pw h2,.pw h3){margin:0;padding:0}
:where(.pw p,.pw li,.pw h1,.pw h2,.pw h3){text-wrap:wrap}
:where(.pw h1,.pw h2,.pw h3){color:inherit}
:where(.pw){overflow-wrap:normal}
.in{max-width:1200px;margin:0 auto;padding:0 32px}
.pad{padding:160px 0}
.pw h2{font-family:var(--head);font-weight:500;font-size:60px;line-height:1.08;letter-spacing:0;margin:0;text-wrap:balance;text-indent:-.0333em}
.intro{margin:24px 0 0;max-width:36em}
.arrows{display:flex;justify-content:flex-end;gap:16px;margin-bottom:64px}
.arr{width:64px;height:64px;border-radius:50%;border:1px solid rgba(1,10,18,.25);background:none;cursor:pointer;display:flex;align-items:center;justify-content:center;padding:0;transition:border-color .3s,background .3s}
.arr:hover{border-color:var(--ink);background:rgba(1,10,18,.04)}
.arr svg{width:22px}
.arr svg *{fill:none;stroke:var(--ink);stroke-width:1.3}
.g{display:grid;grid-template-columns:5fr 7fr;gap:96px;align-items:center}
.essay{aspect-ratio:4/5;width:100%;max-width:440px;border-radius:0;background:var(--ink);color:var(--bone);position:relative;overflow:hidden;display:flex;flex-direction:column;justify-content:flex-end;padding:40px}
.cards .essay+.essay{display:none}
.cards.js .essay{display:none}
.cards.js .essay.on{display:flex}
.essay:before{content:"";position:absolute;inset:0;background:radial-gradient(60% 70% at 70% 30%,rgba(140,91,70,.4),rgba(1,10,18,0) 70%);z-index:1}
.essay .bg{position:absolute;inset:0}
.essay .bg .os-img{position:absolute;inset:0;width:100%;height:100%;aspect-ratio:auto;padding:0;border:0;background:none}
.essay .bg img{width:100%;height:100%;object-fit:cover;display:block;max-width:none}
.essay .sg{position:absolute;right:36px;top:36px;width:120px;z-index:2}
.essay .sg circle{fill:none;stroke:var(--gilt);stroke-width:.7}
.essay .k{position:relative;z-index:2;font-family:var(--label);font-size:11px;letter-spacing:.28em;text-transform:uppercase;color:var(--sand)}
.essay .t{position:relative;z-index:2;font-family:var(--head);font-style:italic;font-weight:500;font-size:36px;line-height:1.15;margin-top:12px;color:var(--bone);text-decoration:none}
.essay .st{position:relative;z-index:2;margin-top:10px;font-size:18px;line-height:1.4;color:var(--stone)}
.essay .up{position:relative;z-index:2;margin-top:22px;padding-top:14px;border-top:1px solid rgba(187,175,163,.3);font-family:var(--body);font-size:17px;line-height:1.45;color:var(--sand)}
.pill{display:inline-flex;align-items:center;gap:14px;margin-top:40px;min-height:64px;padding:0 40px;border-radius:999px;border:1px solid rgba(1,10,18,.25);background:var(--bone);font-family:var(--label);font-size:13px;letter-spacing:.16em;text-transform:uppercase;text-decoration:none;color:var(--ink);transition:border-color .3s,background .3s}
.pill:hover{border-color:var(--ink);background:#f4efe5}
.pill i{display:inline-block;width:16px;height:18px;background:linear-gradient(var(--clay) 0 18%,transparent 18% 32%,var(--clay) 32% 50%,transparent 50% 62%,var(--clay) 62% 100%);clip-path:polygon(0 0,100% 0,100% 100%,50% 78%,0 100%)}
.js-rv .rv{opacity:0;transform:translateY(16px);transition:opacity 1.3s ease,transform 1.3s ease}
.js-rv .rv.on{opacity:1;transform:none}
.js-rv .d1{transition-delay:.12s}
.js-rv .d2{transition-delay:.24s}
@media (max-width:767px){.pw{font-size:19px}.in{padding:0 20px}.pad{padding:88px 0}.pw h2{font-size:40px}.g{grid-template-columns:1fr;gap:32px}.arrows{margin-bottom:32px}.essay{padding:28px}.essay .t{font-size:28px}.essay .sg{width:80px;right:24px;top:24px}.pill{padding:0 26px}}
@media (prefers-reduced-motion:reduce){.js-rv .rv{opacity:1;transform:none;transition:none}}
